nextflow_process {

    name "Test Process RPBP_EXTRACTMETAGENEPROFILES"
    script "../main.nf"
    process "RPBP_EXTRACTMETAGENEPROFILES"

    tag "modules"
    tag "modules_nfcore"
    tag "rpbp"
    tag "rpbp/extractmetageneprofiles"

    test("homo_sapiens chr20 - extract metagene") {

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true, strandedness:'forward' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/aligned_reads/SRX11780888_chr20.bam", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/aligned_reads/SRX11780888_chr20.bam.bai", checkIfExists: true)
                ])
                input[1] = [
                    [ id:'reference' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/rpbp/reference.annotated.bed.gz", checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("homo_sapiens chr20 - extract metagene - stub") {

        options '-stub'

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true, strandedness:'forward' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/aligned_reads/SRX11780888_chr20.bam", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/aligned_reads/SRX11780888_chr20.bam.bai", checkIfExists: true)
                ])
                input[1] = [
                    [ id:'reference' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/rpbp/reference.annotated.bed.gz", checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

